document.addEventListener("DOMContentLoaded",function(){const e=document.querySelectorAll(".nav-item"),t=document.querySelector(".header").clientHeight;e.forEach(e=>{e.addEventListener("click",function(){e.classList.contains("has-menu")&&this.querySelector(".nolan-menu").classList.toggle("open")})}),document.querySelectorAll(".nolan-menu").forEach(e=>{e.addEventListener("mouseleave",function(){this.classList.remove("open")})}),window.addEventListener("resize",()=>{e.forEach(e=>{e.style.setProperty("--header-height",`${t}px`)})})});